{{ config(materialized='table', post_hook="COPY " ~ this ~ " TO '" ~ env_var('FUDOKI_PACKAGE_DIR') ~ "/132195/initial_expenditure_budget.csv' (FORMAT CSV, HEADER TRUE)") }}
